#include <iostream>
#include <string>
#include <algorithm>

int main() {
    std::string s;
    while (std::cin >> s) {
        std::string rev = s;
        std::reverse(rev.begin(), rev.end());
        if (s == rev) std::cout << "YES" << std::endl;
        else std::cout << "NO" << std::endl;
    }
    return 0;
}
